(npm start >/dev/null 2>&1 &) ; sleep 2; cat > $TMPDIR/shot.js <<'E'
const {chromium}=require('playwright');
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1280,height:900}});
await p.goto('http://127.0.0.1:'+process.env.PORT+'/index.html');await p.screenshot({path:process.env.TMPDIR+'/home.png',fullPage:true});
await p.setViewportSize({width:390,height:800});await p.screenshot({path:process.env.TMPDIR+'/m.png',fullPage:true});await b.close()})()
E
cp $TMPDIR/shot.js ./shot.tmp.js && node shot.tmp.js; rm shot.tmp.js; ls $TMPDIR

