/* Page sections. Each block is used by the page named in its comment. */

/* Home */

.hero {
  position: relative;
  overflow: hidden;
  padding: var(--space-8) 0 calc(var(--space-8) + 56px);
  border-bottom: 1px solid var(--color-line);
  background: linear-gradient(180deg, var(--color-brand-tint), var(--color-bg));
}

.hero::before {
  content: '';
  position: absolute;
  top: -140px;
  right: -100px;
  width: 460px;
  height: 460px;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgba(6, 182, 212, 0.2), rgba(6, 182, 212, 0));
}

.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: var(--space-7);
  align-items: center;
}

.hero-copy h1 {
  font-size: 44px;
}

.hero-copy .lede {
  max-width: 480px;
  margin-top: var(--space-4);
}

.hero-actions {
  display: flex;
  gap: var(--space-3);
  margin-top: var(--space-5);
}

.stats-overlap {
  position: relative;
  z-index: 1;
  margin-top: -56px;
}

.feature {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: var(--space-6);
  align-items: center;
  overflow: hidden;
}

.feature-art {
  height: 260px;
  background: linear-gradient(135deg, #0ea5e9, #6366f1);
}

.feature-copy {
  padding: var(--space-5) var(--space-5) var(--space-5) 0;
}

.feature-copy h3 {
  font-size: 22px;
}

.feature-copy .price {
  margin: var(--space-3) 0 var(--space-4);
}

.newsletter {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-6);
  align-items: center;
  padding: var(--space-6);
}

.form-note {
  margin-top: var(--space-2);
  font-size: 13px;
}

/* Products */

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-5);
}

